package com.bank.compose.bad;

import com.bank.compose.capability.StandardFeeCalculator;
import java.math.BigDecimal;

public class InheritanceBasedService extends StandardFeeCalculator {
    // PROBLEMS:
    // 1. Can't extend NotificationService TOO (single inheritance!)
    // 2. Can't swap to DiscountedFeeCalculator at runtime
    // 3. Exposes StandardFeeCalculator's public methods (calculate, getStrategy) — unintended API!
    // 4. Fragile: if StandardFeeCalculator changes, we might break

    public String executeTrade(String symbol, BigDecimal amount) {
        BigDecimal fee = calculate(amount);  // inherited — works, but tightly coupled
        return "Trade " + symbol + " Rs." + amount + " fee Rs." + fee;
    }
}
