// ─── File: src/main/java/com/bank/compose/good/CompositionBasedService.java ───
// ✅ GOOD: HAS-A FeeCalculator + NotificationService + AuditLogger
package com.bank.compose.good;

import com.bank.compose.capability.*;
import java.math.BigDecimal;

public class CompositionBasedService {
    // HAS-A: multiple capabilities via composition
    private final FeeCalculator feeCalculator;
    private final NotificationService notifier;
    private final AuditLogger auditor;

    // Constructor injection — swap at runtime!
    public CompositionBasedService(FeeCalculator feeCalculator,
                                   NotificationService notifier,
                                   AuditLogger auditor) {
        this.feeCalculator = feeCalculator;
        this.notifier = notifier;
        this.auditor = auditor;
    }

    public String executeTrade(String accountId, String symbol, BigDecimal amount) {
        // DELEGATES to each capability:
        BigDecimal fee = feeCalculator.calculate(amount);
        String notification = notifier.notify(accountId, "Trade executed: " + symbol);
        auditor.log("TRADE: " + symbol + " Rs." + amount + " fee Rs." + fee);

        return "Trade " + symbol + " Rs." + amount + " fee Rs." + fee
            + " [" + feeCalculator.getStrategy() + "] — " + notification;
    }

    public AuditLogger getAuditor() { return auditor; }
}
```

```java
// ─── File: src/test/java/com/bank/compose/CompositionVsInheritanceTest.java ───
package com.bank.compose;

import com.bank.compose.bad.InheritanceBasedService;
import com.bank.compose.capability.*;
import com.bank.compose.good.CompositionBasedService;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class CompositionVsInheritanceTest {

    // ═══ INHERITANCE: works but has problems ═══
    @Test
    void inheritance_works_butTightlyCoupled() {
        InheritanceBasedService service = new InheritanceBasedService();
        String result = service.executeTrade("RELIANCE", new BigDecimal("100000"));
        assertThat(result).contains("fee Rs.100");

        // PROBLEM 1: service EXPOSES FeeCalculator methods!
        BigDecimal leaked = service.calculate(new BigDecimal("50000"));
        // ↑ calculate() is inherited public — unintended API leak!
        assertThat(leaked).isNotNull();
    }

    // ═══ COMPOSITION: flexible, multiple capabilities, swappable ═══
    @Test
    void composition_standardFees() {
        CompositionBasedService service = new CompositionBasedService(
            new StandardFeeCalculator(), new NotificationService(), new AuditLogger());

        String result = service.executeTrade("SAV2001", "RELIANCE", new BigDecimal("100000"));
        assertThat(result).contains("fee Rs.100").contains("STANDARD");
    }

    @Test
    void composition_swapToDiscountedFees() {
        CompositionBasedService service = new CompositionBasedService(
            new DiscountedFeeCalculator(),  // SWAPPED! Different strategy!
            new NotificationService(), new AuditLogger());

        String result = service.executeTrade("SAV2001", "RELIANCE", new BigDecimal("100000"));
        assertThat(result).contains("fee Rs.50").contains("DISCOUNTED");
        // Same service, different fee strategy — IMPOSSIBLE with inheritance!
    }

    @Test
    void composition_multipleCapabilities() {
        AuditLogger auditor = new AuditLogger();
        CompositionBasedService service = new CompositionBasedService(
            new StandardFeeCalculator(), new NotificationService(), auditor);

        service.executeTrade("SAV2001", "RELIANCE", new BigDecimal("100000"));

        // Has fee calculation + notification + audit — THREE capabilities!
        assertThat(auditor.getEntries()).hasSize(1);
        assertThat(auditor.getEntries().get(0)).contains("TRADE: RELIANCE");
        // Inheritance: can only extend ONE class. Composition: HAS-A unlimited!
    }

    @Test
    void composition_doesNotLeakInternalMethods() {
        CompositionBasedService service = new CompositionBasedService(
            new StandardFeeCalculator(), new NotificationService(), new AuditLogger());

        // service.calculate(amount) → DOESN'T EXIST! Not exposed!
        // FeeCalculator is INTERNAL — caller only sees executeTrade()
        // Inheritance would expose calculate() publicly — BAD!
        assertThat(true).isTrue();
    }

    // ═══ SUMMARY: PREFER COMPOSITION ═══
    @Test
    void summary() {
        // Composition wins on: flexibility, multiple reuse, encapsulation, testability
        // Inheritance wins on: shared state, true IS-A, template method
        // Default: COMPOSE. Inherit only for true IS-A with shared mutable state.
        assertThat(true).isTrue();
    }
}
```

